function validate([startPos, endPos, k]) {
  for (const [name, value] of [['startPos', startPos], ['endPos', endPos], ['k', k]]) {
    if (!Number.isInteger(value) || value < 1 || value > 1000) return `${name} is an integer from 1 to 1000.`;
  }
  return null;
}

