function numberOfWays(startPos, endPos, k) {
  const MOD = 1000000007;
  const distance = Math.abs(endPos - startPos);
  if (distance > k || (k - distance) % 2 !== 0) {
    return 0;
  }
  const forward = (k + distance) / 2;
  const row = new Array(forward + 1).fill(0);
  row[0] = 1;

  for (let n = 1; n <= k; n++) {
    for (let r = Math.min(n, forward); r >= 1; r--) {
      row[r] = (row[r] + row[r - 1]) % MOD;
    }
  }
  return row[forward];
}

