function numberOfWays(startPos, endPos, k) {
  const MOD = 1000000007;
  let ways = new Map([[startPos, 1]]);
  for (let step = 0; step < k; step++) {
    const next = new Map();
    for (const [pos, count] of ways) {
      next.set(pos - 1, ((next.get(pos - 1) || 0) + count) % MOD);
      next.set(pos + 1, ((next.get(pos + 1) || 0) + count) % MOD);
    }
    ways = next;
  }
  return ways.get(endPos) || 0;
}

