function generate(rand, size) {
  const limit = size === 'large' ? 1000 : 12;
  const k = 1 + Math.floor(rand() * limit);
  const startPos = 1 + Math.floor(rand() * (size === 'large' ? 1000 : 15));
  let endPos;
  if (rand() < 0.7) {
    // Pick a reachable target most of the time so the answers are interesting.
    const offset = Math.floor(rand() * (k + 1));
    const signed = (rand() < 0.5 ? -1 : 1) * (offset - ((k - offset) % 2));
    endPos = Math.min(1000, Math.max(1, startPos + signed));
  } else {
    endPos = 1 + Math.floor(rand() * (size === 'large' ? 1000 : 15));
  }
  return [startPos, endPos, k];
}
